import assert from 'node:assert/strict';import {CORE_CHART_TYPES,prepareCoreChart,CoreChartError} from '../core/core_chart_engine.mjs';
function fixture(t){if(['Scatter Plot','Regression Scatter','Bubble Plot','Strip / Dot Plot'].includes(t))return{points:[{x:1,y:2,r:3},{x:2,y:4,r:5},{x:3,y:3,r:2}]};if(['Histogram','Box Plot','Violin Plot','ECDF'].includes(t))return{values:[1,2,2,3,4,5,8,13]};if(t==='Treemap')return{nodes:[{id:'a',value:4},{id:'b',value:2}]};if(t==='Sankey')return{nodes:[{id:'a'},{id:'b'},{id:'c'}],links:[{source:'a',target:'b',value:4},{source:'b',target:'c',value:3}]};return{categories:['A','B','C','D'],series:[{name:'S1',values:[4,7,3,8]},...(['Grouped Bar','Stacked Bar','100% Stacked Bar','Paired Before/After Bars','Dumbbell','Slope Chart','Multi-Line','Stacked Area'].includes(t)?[{name:'S2',values:[3,2,6,4]}]:[])]};}
const fps=new Set();for(const t of CORE_CHART_TYPES){const a=prepareCoreChart(t,fixture(t)),b=prepareCoreChart(t,fixture(t));assert.equal(a.fingerprint,b.fingerprint);assert.deepEqual(a,b);fps.add(a.fingerprint)}assert.equal(CORE_CHART_TYPES.length,29);assert.equal(fps.size,29);assert.throws(()=>prepareCoreChart('Pie',{categories:['A'],series:[{values:[NaN]}]}),CoreChartError);assert.throws(()=>prepareCoreChart('Sankey',{nodes:[{id:'a'}],links:[]}),CoreChartError);console.log(JSON.stringify({pass:true,types:29,deterministic:true,typedEligibility:true,invalidInputBlocking:true},null,2));
